window.KAFKA_HIGHLIGHTS={"\u0938\u0924\u094d\u0924\u093e\u0915\u094b \u092e\u0939\u093e\u092d\u093e\u0930\u0924, \u0938\u091e\u094d\u091c\u092f\u0915\u094b \u0930\u093f\u092a\u094b\u0930\u094d\u091f\u093f\u0919\u094d\u0917, \u0939\u093e\u092e\u0940 \u0927\u0943\u0924\u0930\u093e\u0937\u094d\u091f\u094d\u0930\u0939\u0930\u0942\u0964":{text:"\u0939\u094b\u0907\u0928, \u0928\u093f\u0938\u094d\u0915\u0928\u094d\u091b\u094c  \u0907\u0928\u094d\u091f\u0930\u0928\u0947\u091f \u0930 \u092a\u0924\u094d\u0930 \u092a\u0924\u094d\u0930\u093f\u0915\u093e\u092e\u093e \u0906\u092b\u094d\u0928\u094b \u092e\u093e\u0928\u094d\u091b\u0947 \u0930 \u0915\u0941\u0930\u093e\u0915\u094b \u0938\u092e\u0930\u094d\u0925\u0928\u092e\u093e \u0905\u0928\u093f \u0935\u094d\u092f\u0938\u094d\u0924 \u0939\u0941\u0928\u094d\u091b\u094c\u0901, \u0939\u094b-\u0939\u0932\u094d\u0932\u093e \u0905\u0928\u093f \u0935\u093f\u092a\u0915\u094d\u0937\u0940\u0932\u093e\u0908 \u0928\u093e\u0928\u093e \u092d\u093e\u0901\u0924\u0940 \u0917\u093e\u0932\u0940 \u0917\u0930\u094d\u0928\u0964",poem:false},"Oh! Arsenal.. you have never made me feel so proud.":{text:"I am sorry, boss, for all you have done for the club you deserved a whole lot more respect than what you got from us.",poem:false},"\u0915\u0925\u093e: \u092a\u0932\u094d\u092a\u0938\u093e\u0915\u094b \u091a\u093f\u0920\u094d\u0920\u0940\u0964":{text:'"\u092a\u094d\u0930\u0935\u0947\u0936, \u091c\u0940\u0935\u0928 \u0915\u0947 \u0939\u094b \u091c\u0938\u094d\u0924\u094b \u0932\u093e\u0917\u094d\u091b?" \u090f\u0915 \u0926\u093f\u0928 \u090f\u0915\u094d\u0915\u093e\u0938\u093f \u092a\u094d\u0930\u0936\u094d\u0928 \u0917\u0930\u0947\u0915\u0940 \u0925\u093f\u0908 \u092a\u0932\u094d\u092a\u0938\u093e\u0932\u0947, "\u0924\u093f\u092e\u093f\u0932\u093e\u0908 \u0906\u092b\u0942\u0932\u0947 \u092a\u093e\u090f\u0915\u094b \u092f\u094b \u0938\u092e\u092f \u092a\u094d\u0930\u0924\u093f \u091c\u0938\u094d\u091f\u093f\u0938 \u0917\u0930\u0947\u091c\u0938\u094d\u0924\u094b \u0932\u093e\u0917\u094d\u091b \u0924?',poem:false},"\u0906\u091c \u092e\u0947\u0930\u094b \u091c\u0928\u094d\u092e\u0926\u093f\u0928\u0964":{text:"\u0915\u0947\u0939\u0940 \u0917\u0941\u092e\u093e\u090f \u091c\u0938\u094d\u0924\u094b, \u0915\u0947\u0939\u0940 \u0939\u0930\u093e\u090f \u091c\u0938\u094d\u0924\u094b,\n\u0938\u0902\u0938\u093e\u0930 \u091c\u093f\u0924\u094d\u0928\u0947 \u092a\u094d\u0930\u0924\u093f\u0938\u094d\u092a\u0930\u094d\u0927\u093e\u092e\u093e \u092d\u093e\u0917 \u0928\u0948 \u0928\u0932\u093f\u0907 \u0939\u093e\u0930\u0947\u0930,\n\u0905\u0928\u0935\u0930\u0924 \u091a\u0932\u093f\u0930\u0939\u0947\u0915\u094b \u092a\u093e\u0939\u0921\u0940 \u092e\u0928: \u0905\u0938\u094d\u0924\u093f\u0924\u094d\u0935 \u092f\u093e\u0924\u094d\u0930\u093e\u0964",poem:true},"\u092a\u094d\u0930\u0938\u094d\u0928 \u0938\u094b\u0927\u094d\u092f\u094b \u092d\u0928\u0947\u0930 \u092a\u091b\u0940 \u0932\u093e\u0917\u094d\u0928\u0947 \u0939\u0930\u0942\u0932\u093e\u0908 \u091c\u0935\u093e\u092b\u0964":{text:"\u092c\u094b\u0932\u0940\u0928\u0948 \u092e\u0928 \u0928\u092a\u0930\u0947\u0915\u094b \u0935\u093e \u092e\u091c\u0948 \u0932\u093f\u090f\u0915\u094b \u092d\u090f\u092a\u0928\u093f, \u092c\u094b\u0932\u094d\u0928 \u092a\u0930\u094d\u0928\u0947 \u0920\u093e\u0909\u0901\u092e\u093e \u091a\u0932\u0947\u0915\u094b \u0928\u0948 \u091b, \u092c\u094b\u0932\u094d\u0928 \u0928\u092a\u0930\u0940 \u092a\u0928\u093f \u091a\u0932\u093f\u0930\u0939\u0947\u0915\u094b \u0920\u093e\u0909\u0901\u092e\u093e \u0928\u091a\u0932\u0947\u0930 \u0915\u0947 \u0928\u0948 \u0939\u0941\u0928\u0947 \u0939\u094b \u0930\u0964",poem:false},"\u0927\u0941\u0935\u093e\u0901\u092e\u093e \u091a\u0932\u0947\u0915\u094b \u0938\u0939\u0930":{text:"\u0938\u0939\u0930\u092e\u093e \u0938\u092c\u0948\u0932\u0947-\n\u0920\u0947\u0917\u093e\u0928\u093e \u0938\u094b\u0927\u094d\u0926\u0948 \u0939\u093f\u0901\u0921\u094d\u091b\u0928\u094d,\n\u0924\u0930 \u092f\u0939\u093e\u0901 \u0915\u0938\u0948\u0932\u093e\u0908-",poem:true},"\u0906\u092b\u094d\u0928\u0948 \u0938\u0902\u0938\u094d\u092e\u0930\u0923 \u0967- \u0915\u093f\u0924\u093e\u092c\u0915\u093e \u0915\u0941\u0930\u093e":{text:"\u2018\u092c\u094d\u0930\u0924 \u0915\u093f\u0928 \u092c\u0938\u094d\u0928\u092a\u0930\u094d\u0928\u0947\u2019, \u2018\u092a\u093e\u0928\u0940 \u0916\u093e\u0928 \u0915\u093f\u0928 \u0928\u0939\u0941\u0928\u0947\u2019, \u2018\u0915\u0947-\u0915\u093e \u0932\u093e\u0917\u093f\u2019,\n\u2018\u091b\u094b\u0930\u093e \u0928\u092d\u090f \u092e\u0940\u0924 \u091b\u094b\u0930\u093e\u0932\u093e\u0908 \u0915\u093f\u0928 \u0926\u093f\u0928 \u092a\u0930\u094d\u0928\u0947 \u0930\u0947, \u091b\u094b\u0930\u0940\u0932\u093e\u0908 \u0926\u093f\u090f \u0915\u0947 \u0939\u0941\u0928\u094d\u091b\u2019,",poem:true},"\u0906\u092b\u094d\u0928\u0948 \u0938\u0902\u0938\u094d\u092e\u0930\u0923 \u0968- \u0915\u0935\u093f\u0924\u093e\u0915\u093e \u0915\u0941\u0930\u093e":{text:"\u0906\u092b\u094d\u0928\u0948 \u0938\u094d\u0924\u0930\u0915\u094b \u0939\u094b\u0932\u093e, \u0905\u0928\u093f \u092c\u093e\u092c\u093e\u0932\u0947 \u0925\u093e\u0939 \u0928\u092a\u093e\u090f \u0905\u0930\u0941\u0932\u0947 \u0915\u0947 \u0925\u093e\u0939 \u092a\u093e\u0909\u0932\u093e\u0928 \u092d\u0928\u0947\u0930 \u0926\u0947\u0916\u093e\u090f\u0901, \u2018\u091c\u093f\u091c\u0940\u0935\u093f\u0937\u093e\u2019 \u0936\u092c\u094d\u0926 \u092a\u0930\u0947\u091b \u092e\u0930\u093f\u0917\u090f \u0905\u0930\u094d\u0925 \u0906\u0909\u0928\u0941 \u0930 \u0906\u092b\u0942\u0932\u093e\u0908\u0964 \u090f\u0915 \u092d\u093e\u0930\u0940 \u0938\u093e\u0939\u093f\u0924\u094d\u092f\u093f\u0915 \u0907\u0924\u093f\u0939\u093e\u0938 \u0930 \u092a\u094d\u0932\u093e\u0917\u0930\u093f\u091c\u092e \u092c\u093e\u0930\u0947 \u0915\u0941\u0930\u093e \u0938\u0941\u0928\u0947\u092a\u091b\u093f, \u0906\u092b\u0948 \u092a\u094d\u0930\u092f\u093e\u0938 \u0917\u0930\u0947\u0930 \u092a\u0939\u093f\u0932\u094b \u092a\u091f\u0915 \u0932\u0947\u0916\u0947\u0925\u0947\u0901\u0964 \u092e \u0926\u094b\u0938\u094d\u0930\u094b \u092d\u090f\u0901, \u090f \u0932\u0947\u0916\u0947 \u0924 \u0939\u0941\u0928\u0947 \u0930\u0939\u0947\u091b \u092d\u0928\u0947\u0930 \u0915\u0932\u092e\u0932\u0947 \u092c\u093e\u0939\u094d\u0930\u0916\u0930\u0940 \u0938\u0941\u0930\u0941 \u0917\u0930\u094d\u092f\u094b \u0924\u094d\u092f\u0938\u0948\u0917\u0930\u093f \u0928\u0948\u0964",poem:true},"\u092d\u093e\u0935\u0938\u0941\u0928\u094d\u092f:":{text:"\u0928\u0938\u094d\u091f\u094d\u092f\u093e\u0932\u094d\u091c\u093f\u092f\u093e \u092b\u094d\u092f\u093e\u0928\u094d\u091f\u093e\u0938\u0940\u092e\u093e-\n\u0905\u0921\u093f\u090f\u0915\u094b- \u0905\u0928\u0935\u0930\u0924 \u0905\u0938\u094d\u0924\u093f\u0924\u094d\u0935 \u092f\u093e\u0924\u094d\u0930\u093e,\n\u092e\u093e\u0928\u094c\u0902 \u092a\u0939\u093f\u0932\u094b \u0938\u0941\u0932\u094d\u091f\u094b \u091c\u0941\u0932\u0942\u0938 \u0939\u094b \u0907\u0924\u093f\u0939\u093e\u0938\u0915\u094b\u0964",poem:true},"\u0938\u092a\u0928\u093e\u0915\u093e \u092f\u0925\u093e\u0930\u094d\u0925\u0939\u0930\u0942\u0964":{text:"\u0924\u094d\u092f\u0938\u092a\u091b\u093f \u0938\u094b\u091a\u094d\u091b\u0941-\n\u0915\u0938\u094d\u0915\u093e \u0932\u093e\u0917\u093f \u0939\u0941\u0928\u094d \u092f\u0940 \u0938\u092a\u0928\u093e\u0939\u0930\u0942?\n\u0915\u0947\u0915\u093e \u0932\u093e\u0917\u093f \u0939\u0941\u0928\u094d \u092f\u0940 \u0938\u092a\u0928\u093e\u0939\u0930\u0942?",poem:true},"\u090a-\u0927\u094d\u0930\u0941\u0935, \u092e-\u092a\u0930\u093f\u0915\u094d\u0930\u092e\u093e":{text:"\u0917\u0941\u0928\u0917\u0941\u0928\u093e\u0909\u0901\u091b\u0928  \u0909\u0938\u0915\u093e \u0905\u0927\u0930,\n\u0909\u0938\u0915\u094b \u0915\u0947\u0936\u0930\u093e\u0936\u0940\u0915\u094b \u0932\u0939\u0930\u092e\u093e,\n\u0939\u0930\u093e\u090f\u0915\u093e \u092e\u0947\u0930\u093e \u0915\u0941\u0923\u094d\u0920\u093e\u0939\u0930\u0942\u0964",poem:true},"\u0939\u094b, \u092e \u092c\u0939\u0941\u0932\u093e \u0939\u0941\u0901\u0964":{text:"\u092e\u0948\u0932\u0947 \u0935\u094d\u0930\u093f\u0928\u094d\u0926\u093e\u0932\u093e\u0908 \u0917\u0930\u0947\u0915\u094b \u091b\u0932 \u092a\u0928\u093f \u0926\u0947\u0916\u0947\u0901,\n\u092e\u0948\u0932\u0947 \u0938\u0940\u0924\u093e\u092e\u093e\u0925\u0940 \u0917\u0930\u0947\u0915\u094b \u0905\u0928\u094d\u092f\u093e\u092f \u092a\u0928\u093f \u0926\u0947\u0916\u0947\u0901,\n\u092e\u0948\u0932\u0947 \u0915\u0943\u0937\u094d\u0923\u0915\u094b \u091b\u0932-\u0915\u092a\u091f \u092a\u0928\u093f \u0926\u0947\u0916\u0947\u0901\u0964",poem:true},"Like a Rolling Stone- No Direction Home":{text:"A breakup where it\u2019s not exactly clear what has gone wrong, but where two people have simply fallen out of love.",poem:false},Muse:{text:"haunt me beautiful-\nhaunt me beautifully,\nbit by bit, then all at once?",poem:true},"dreams, poetry, sunsets.":{text:"you do not see it as it is,\nyou see it as you are,\nthe world needs happier endings.",poem:true},"\u092e\u0947\u0930\u094b \u0928\u093f\u0928\u094d\u0926\u094d\u0930\u093e\u0964 \u092e\u0947\u0930\u094b \u0926\u0947\u0936\u0964":{text:"\u0938\u092c\u0948 \u0909\u0938\u094d\u0924\u0948-\n\u0938\u092c\u0948 \u0939\u0928\u0941\u092e\u093e\u0928- \u0938\u092c\u0948\u0915\u094b \u092a\u0941\u091a\u094d\u091b\u0930 \u0932\u093e\u092e\u094b,\n\u0939\u091c\u093e\u0930\u094c\u0902 \u092e\u0941\u0926\u094d\u0926\u093e- \u0905\u0928\u0917\u093f\u0928\u094d\u0924\u0940 \u0930\u092e\u093f\u0924\u093e\u0964",poem:true},"\u092e \u0917\u0930\u094d\u092d\u0935\u0924\u093f \u092e\u093e\u0928\u094d\u091b\u0947, \u092e\u0932\u093e\u0908 ..":{text:"\u091c\u0939\u093e\u0901 \u0909\u091c\u094d\u092f\u093e\u0932\u094b- \u0930\u093e\u0924\u0915\u094b \u0905\u0932\u094d\u091d\u093f\u090f\u0915\u094b \u0927\u093e\u0917\u094b-\n\u092a\u0916\u093e\u0932\u093f\u0928 \u092c\u093e\u0901\u0915\u0940 \u0905\u0901\u0927\u094d\u092f\u093e\u0930\u094b\u0915\u094b\n\u0915\u0941\u0930\u0942\u092a \u0905\u0935\u0936\u0947\u0937 \u092e\u093e\u0924\u094d\u0930\u0948 \u0928\u0939\u094b\u0938\u0964",poem:true},"\u090f! \u0924\u093f\u092e\u093f\u0964":{text:"\u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915- \u0905\u0902\u0917-\u092a\u094d\u0930\u0924\u094d\u092f\u0902\u0917\n\u090f\u0915-\n\u0905\u0930\u094d\u0915\u093e\u092e\u093e \u092c\u093f\u0932\u092f \u0939\u0941\u0928\u0947 \u0915\u0932\u094d\u092a\u0928\u093e\u0964",poem:true},"\u092e\u094c\u0928 \u092c\u0941\u0926\u094d\u0927\u0964":{text:"\u091a\u093f\u0935\u0930 \u0935\u0938\u094d\u0924\u094d\u0930\u092e\u093e \u092f\u0924\u093f\u0916\u0947\u0930 \u0930\u093e\u091c\u092e\u0939\u0932\u0915\u094b \u0922\u094b\u0915\u093e\u092e\u093e,\n\u0909\u092d\u093f\u090f\u0915\u094b \u091b \u092f\u094c\u091f\u093e \u092d\u0941\u0924\u092a\u0942\u0930\u094d\u0935 \u0930\u093e\u091c\u0915\u0941\u092e\u093e\u0930,\n\u092e\u093e\u0917\u094d\u0928 \u0906\u092f\u094b \u0915\u093f \u0926\u093f\u0928 \u0906\u092f\u094b \u0909?",poem:true},"note to self.":{text:"in the corners of your head today,\nremember- today is not all our yesterday\nwe are not all about our yesterdays.",poem:true},"\u092e\u094c\u0928 \u092a\u094d\u0930\u0924\u093f\u092c\u093f\u092e\u094d\u092c":{text:"\u091b\u0941\u0928 \u0916\u094b\u091c\u094d\u0926\u093e \u0905\u091d\u0948 \u091f\u093e\u0922\u093f\u0928\u0947\n\u092e\u0947\u0930\u094b \u0938\u092a\u0928\u093e\u092d\u093f\u0924\u094d\u0930\u0915\u094b \u0936\u0939\u0930\u092e\u093e\n\u091b\u093e\u090f\u0915\u094b \u0915\u0947\u0935\u0932 \u0905\u0930\u094d\u0927\u091a\u0928\u094d\u0926\u094d\u0930\u092e\u093e\u0964",poem:true},"sunset hues, again with the blues.":{text:"not to save us,\nnot to prove a point,\nnot for applause.",poem:true},"\u0915\u093e\u0930\u094d\u0915\u0940 \u0926\u093e\u0908, \u0930\u093e\u091c\u093e, \u0917\u0923\u0924\u0928\u094d\u0924\u094d\u0930\u0964":{text:"\u0917\u0923\u0924\u0928\u094d\u0924\u094d\u0930 \u0930\u0939\u0947 \u0928\u0948 \u0915\u0947 \u0939\u0941\u0928\u094d\u091b?\n\u092e\u0932\u093e\u0908 \u0924 \u0924\u094d\u092f\u0939\u0940 \u092d\u090f \u0939\u0941\u0928\u094d\u091b-\n\u091c\u094b \u0939\u0930\u0947\u0915 \u092c\u093f\u0939\u093e\u0928 \u0915\u093e\u092e \u0926\u093f\u0928\u094d\u091b\u0964",poem:true},"\u0905\u0928\u0941\u0924\u094d\u0924\u0930\u093f\u0924 \u0916\u0932\u094d\u0926\u0941\u0932\u0940\u0939\u0930\u0942\u0964":{text:"\u092d\u093f\u0937\u094d\u092e\u092a\u093f\u0924\u093e\u092e\u0939\u0915\u094b \u0924\u092a\u0937\u094d\u092f\u093e\u0939\u0930\u0942\u0915\u094b\n\u0935\u0943\u0924\u093e\u0928\u094d\u0924 \u0915\u094b\u0939\u093f \u0938\u0941\u0928\u093e\u0909\u0901\u0926\u0948\u0928\u0928\u094d,\n\u0930 \u0906\u0930\u094d\u091c\u0941\u0928\u0915\u094b \u0938\u093e\u0939\u0938\u0940 \u0917\u093f\u0924 \u0915\u094b\u0939\u0940 \u0917\u093e\u0909\u0901\u0926\u0948\u0928\u0928\u094d\u0964",poem:true},"\u0926\u0947\u0936\u092d\u0915\u094d\u0924\u093f\u0964":{text:"\u0926\u0915\u094d\u0937\u093f\u0923 \u0939\u093e\u0935\u093e\u0939\u0930\u0942 \u0924\u094d\u092f\u0938\u0948\u0917\u0930\u093f \u092c\u0939\u093f\u0930\u0939\u0947,\n\u0916\u0948 \u0924, \u0915\u0938\u0948\u092e\u093e \u092a\u0928\u093f-\n\u0926\u0947\u0936\u092d\u0915\u094d\u0924\u093f \u091c\u093e\u0917\u0943\u0924 \u092d\u093e \u2018\u091b\u0948\u0928 \u0964",poem:true},"\u0913\u091c\u093f\u092e\u093e\u0928\u094d\u0921\u093f\u092f\u0938\u0915\u094b \u092e\u0930\u0941\u092d\u0942\u092e\u093f\u092e\u093e \u0935\u093f\u091c\u092f\u0940\u0939\u0930\u0942\u0915\u094b \u0917\u093e\u0925\u093e\u0964":{text:"\u0938\u094d\u0932\u094b \u092a\u094b\u0907\u091c\u0928\u0915\u094b \u0938\u093f\u0915\u093e\u0930 \u092d\u090f\u0915\u094b \u0925\u093f\u092f\u094b,\n\u0909\u0938\u0915\u094b \u0938\u0902\u0938\u093e\u0930 \u091c\u093f\u0924\u094d\u0928\u0947 \u0918\u094b\u0921\u093e\u0932\u0947\n\u0924\u094d\u092f\u094b \u091f\u093e\u092a\u0941 \u0915\u0939\u093f\u0932\u094d\u092f\u0948 \u092d\u0947\u091f\u0947\u0928\u0964",poem:true},"\u0918\u0928\u0918\u094b\u0930\u0915\u093e \u0906\u0901\u0927\u093f\u092a\u0941\u0930\u093e\u0923\u0939\u0930\u0942\u0964":{text:"\u0938\u093f\u0915\u093f\u0938\u0915\u0947 \u092a\u091b\u093f \u0905\u092c:\n\u0936\u092c\u094d\u0926\u0939\u0930\u0942- \u0928\u094d\u092f\u093e\u0928\u094b \u0930\u0939\u0947\u0928\u0928\u094d\n\u092a\u094d\u0930\u0936\u094d\u0928\u0939\u0930\u0942- \u092a\u094d\u0930\u0936\u094d\u0928 \u0930\u0939\u0947\u0928\u0928\u0964",poem:true},"\u091a\u0924\u0941\u0930\u0947\u0915\u094b \u0926\u0936 \u0932\u093e\u0916\u0915\u094b \u0938\u092a\u0928\u093e\u0964":{text:"\u0915\u0924\u093e\u092c\u093e\u091f \u091f\u093f\u092d\u0940\u092e\u093e \u0926\u0947\u0916\u0947\u091b-\n\u0917\u093e\u0921\u0940\u0932\u0947 \u092e\u093e\u0928\u094d\u091b\u0947 \u0915\u093f\u091a\u094d\u092f\u094b \u092d\u0928\u0947\n\u0926\u0936 \u0932\u093e\u0916 \u0915\u094d\u0937\u0924\u093f\u092a\u0942\u0930\u094d\u0924\u093f!",poem:true},"old house across the street..":{text:"if the children told the old man,\nor raided the ceilings first-\ni was young to know.",poem:true},"she is not here- but she is everywhere.":{text:"and that knowing,\nsoftens me.\nmy being.",poem:true},"On This Tiny pale blue Dot, Why Such Deep Divides?":{text:"Her concern wasn\u2019t the girl, it was the fear of society- the priest refusing to perform funeral rites, the gossip, the boycott.",poem:false},"\u0915\u093e\u0932\u094b \u092c\u093f\u0930\u093e\u0932\u094b, \u0939\u093e\u092e\u0940\u0964":{text:"\u090f\u0921\u092a\u094d\u091f\u0947\u0921 \u0939\u093e\u092e\u0940,\n\u0913\u092d\u0930 \u092a\u0947\u0938\u0947\u0928\u094d\u091f;\n\u0927\u0948\u0930\u094d\u092f\u0935\u093e\u0928-\u0938\u0939\u0928\u0936\u0940\u0932\u0964",poem:true},"DNA Day: Rosalind Franklin and the Forgotten Heroes of DNA.":{text:"The next morning, Watson went to London to tell Wilkins, \u2018Pauling also proposed a non-working DNA model just like ours.\u2019",poem:false},"blue.. ode to you.":{text:"sad eyes are going to be the ruins of me,\nit feels a little dark but i am alright babe,\nmy feelings will learn to cope.",poem:true},"\u0930\u094b\u091c\u093e\u0932\u093f\u0928\u094d\u0921 \u092b\u094d\u0930\u092f\u093e\u0919\u094d\u0915\u0932\u093f\u0928 \u0930 \u0905\u0930\u0942":{text:"\u0928\u094d\u092f\u0941\u0915\u094d\u0932\u093f\u092f\u094b\u091f\u093e\u0907\u0921\u092d\u093f\u0924\u094d\u0930 \u0939\u0941\u0928\u0947 \u092b\u094b\u0938\u094d\u092a\u0947\u091f, \u091a\u093f\u0928\u0940 \u0905\u0928\u093f \u0928\u093e\u0907\u091f\u094d\u0930\u094b\u091c \u092c\u0947\u0938\u0932\u093e\u0908 \u0916\u094b\u0924\u0932\u0947\u0930 \u092a\u094d\u0930\u0938\u094d\u091f \u092a\u093e\u0930\u094d\u0928\u0947 \u0915\u093e\u092e\u091a\u093e\u0939\u093f\u0901 \u0905\u0932\u0947\u0915\u094d\u091c\u0947\u0928\u094d\u0921\u0930 \u091f\u094b\u0921\u0932\u0947 \u0928\u093f\u0915\u0948 \u092a\u091b\u093f \u0917\u0930\u0947\u0915\u093e \u0925\u093f\u090f\u0964",poem:false},"Hippies: Marijuana, Music, Magic Bus and Kathmandu":{text:"As the decade turned, the music, the movement, and the spirit all began to shift outwards, towards the mythical East.",poem:false},"\u0938\u093e\u0901\u091d\u0915\u094b \u092e\u094c\u0928\u0924\u093e\u0964":{text:"\u092e \u0921\u0930\u093e\u0909\u0901\u0926\u093f\u0928 \u0909\u0938\u092d\u093f\u0924\u094d\u0930\u0915\u094b \u0936\u0942\u0928\u094d\u092f\u0938\u0901\u0917;\n\u0909\u0938\u0932\u0947 \u0926\u0947\u0916\u0947\u0915\u094b \u0916\u093e\u0932\u0940\u092a\u0928\u092e\u093e\n\u092e \u0906\u092b\u094d\u0928\u0948 \u092a\u094d\u0930\u0924\u093f\u092c\u093f\u092e\u094d\u092c \u092d\u0947\u091f\u094d\u091b\u0941\u0964",poem:true},"\u092e, \u0924\u093f\u092e\u0940, \u0939\u093e\u092e\u0940":{text:"\u0924\u093f\u092e\u0940- \u092e \u092e\u0947\u091f\u094d\u0928 \u0928\u0938\u0915\u094d\u0928\u0947 \u0930\u0939\u0938\u094d\u092f\u0964\n\u092e- \u0924\u093f\u092e\u0940\u0932\u0947 \u092c\u0938\u094b\u092c\u093e\u0938 \u0917\u0930\u094d\u0928\u0947 \u092e\u094c\u0928\u0924\u093e\u0964",poem:true},"\u092e\u093e\u0928\u0941\u0937\u0940: \u092d\u0941\u092a\u0940\u0938\u0901\u0917\u0915\u093e \u0925\u093e\u0901\u0924\u0940 \u0938\u0902\u0935\u093e\u0926\u0964":{text:"\u0924\u093f\u092e\u0940\u0939\u0930\u0942\u0932\u0947 \u092e\u0932\u093e\u0908 \u091a\u093f\u0928\u0947\u0915\u093e \u0925\u093f\u092f\u094c,\n\u0924\u093f\u092e\u0940\u0939\u0930\u0942\u0932\u0947 \u092e\u0932\u093e\u0908 \u0928\u093f\u092f\u093e\u0932\u0940\u0930\u0939\u0947\u0915\u093e \u0925\u093f\u092f\u094c -\n\u092e\u0947\u0930\u094b \u0936\u0930\u0940\u0930\u0915\u094b \u0939\u0930\u0947\u0915 \u091a\u093e\u0932, \u0939\u0930\u0947\u0915 \u0915\u092e\u091c\u094b\u0930\u0940\u0964",poem:true},"\u092c\u0941\u0926\u094d\u0927 \u0935\u093e\u091c \u092c\u0930\u094d\u0928 \u0907\u0928 \u0928\u0947\u092a\u093e\u0932\u0964":{text:"\u0939\u094d\u092f\u093e\u0938\u091f\u094d\u092f\u093e\u0917 \u092e\u093e \u0930\u093e\u0916\u0947\u0930,\n#BuddhawasBornInNepal\n\u092c\u0941\u0926\u094d\u0927 \u0928\u0947\u092a\u093e\u0932\u092e\u093e \u091c\u0928\u094d\u092e\u0947\u0915\u094b \u0939\u094b\u0964",poem:true},"echoes of faded love.":{text:"like how the wind remembers\nthe shape of a window\nlong after it\u2019s shut.",poem:true},"\u092a\u0930\u092e\u094d\u092a\u0930\u093e\u0915\u094b \u0915\u093e\u0930\u093e\u0917\u093e\u0930":{text:"\u0909\u0938\u0915\u094b \u091b\u093e\u092f\u093e\u0901 \u092c\u093f\u091d\u0940\u0939\u0930\u092f\u094b,\n\u0918\u0923\u094d\u091f \u092c\u0928\u093e\u0909\u0928\u0947 \u0909\u0938\u0915\u093e \u0939\u093e\u0924\u0932\u093e\u0908\n\u092a\u094d\u0930\u0938\u093e\u0926 \u091a\u093e\u0916\u094d\u0928 \u092a\u094d\u0930\u0924\u093f\u092c\u0928\u094d\u0927 \u0917\u0930\u093f\u092f\u094b\u0964",poem:true},"\u092e \u0925\u0930 \u0928\u092d\u090f\u0915\u094b \u0906\u0924\u094d\u092e\u093e\u0964":{text:"\u0924\u094d\u092f\u0939\u0940 \u092e\u094c\u0928\u0924\u093e \u091c\u0938\u0932\u0947\n\u0939\u093e\u092e\u0940\u0932\u093e\u0908 \u091c\u093e\u0924\u0915\u094b- \u0905\u0928\u094d\u0927\u0915\u093e\u0930\u092e\u093e \u0917\u093e\u0921\u094d\u092f\u094b,\n\u091c\u0939\u093e\u0901 \u0927\u0930\u094d\u092e \u090f\u0915 \u092d\u094d\u0930\u092e, \u0930 \u0905\u0927\u0930\u094d\u092e \u0928\u0948 \u092a\u0930\u092e\u094d\u092a\u0930\u093e\u0964",poem:true},"\u0926\u0947\u0936 \u0939\u0930\u093e\u090f\u0915\u094b \u0938\u092a\u0928\u093e":{text:"\u0938\u092a\u0928\u093e \u092c\u0947\u091a\u094d\u0928\u0947\u0939\u0930\u0942 \u0938\u093f\u0902\u0939\u0926\u0930\u092c\u093e\u0930\u092e\u093e \u091b\u0928\u094d:\n\u091a\u093e\u0909\u0930\u093f\u090f\u0915\u094b \u091d\u0928\u094d\u0921\u093e,\n\u091d\u0941\u091f\u093e \u0928\u093e\u0930\u093e\u0915\u094b \u092a\u0930\u094d\u0926\u093e\u0964",poem:true},"\u092e \u092a\u094d\u0930\u0936\u094d\u0928 \u0938\u094b\u0927\u094d\u0928\u0947 \u092e\u093e\u091f\u094b\u0964":{text:"\u0924\u093f\u092e\u094d\u0930\u093e \u0935\u093e\u0915\u094d\u092f\u0939\u0930\u0942 \u092c\u094b\u0915\u0941\u0901?\n\u0905\u092c \u092e \u092a\u094d\u0930\u0936\u094d\u0928 \u092e\u093e\u0924\u094d\u0930\u0948 \u0939\u094b\u0907\u0928-\n\u0909\u0924\u094d\u0924\u0930 \u0916\u094b\u091c\u094d\u0928\u0947 \u092d\u0942\u092e\u093f \u0939\u0941\u0901\u0964",poem:true},"\u0918\u093e\u092e \u0930 \u092b\u0942\u0932\u0915\u094b \u092a\u094d\u0930\u0947\u092e \u0917\u0940\u0924\u0964":{text:"\u092c\u093f\u0939\u093e\u0928 \u092b\u0947\u0930\u093f \u092b\u0915\u094d\u0930\u093f\u0928\u0947 \u0906\u0936\u093e\u092e\u093e\n\u090f\u0915 \u0924\u092e\u093e\u0938 \u0906\u0901\u0916\u093e \u091a\u093f\u092e\u094d\u0932\u0928\u094d\u091b,\n\u0909\u091c\u094d\u092f\u093e\u0932\u094b\u0915\u094b \u092a\u094d\u0930\u0924\u0940\u0915\u094d\u0937\u093e\u092e\u093e \u0930\u093e\u0924 \u092c\u093e\u0901\u091a\u094d\u091b\u0964",poem:true},"Between Two Rivers":{text:"This was also the time when the land bridge that once connected Europe with Britain, or Alaska and Siberia got buried by the rising sea.",poem:false},"\u0932\u0935-\u0915\u0941\u0936\u0915\u094b \u0928\u093e\u0917\u0930\u093f\u0915\u0924\u093e\u0964":{text:"\u0930\u093e\u0935\u0923\u0932\u0947 \u0905\u092a\u0939\u0930\u0923 \u0917\u0930\u094d\u0926\u093e \u092e\u0947\u0930\u094b \u0906\u0901\u0938\u0941 \u0915\u0939\u093e\u0901 \u0916\u0938\u0947?\n\u092e\u0948\u0932\u0947 \u092e\u093e\u0924\u094d\u0930 \u0915\u093f\u0928 \u0926\u093f\u0928\u0941\u092a\u0930\u094d\u200d\u092f\u094b -\n\u0924\u093f\u092e\u0940\u0932\u093e\u0908 \u092a\u0935\u093f\u0924\u094d\u0930\u0924\u093e\u0915\u094b \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930?",poem:true},"From Flood to Fields":{text:"While mythological, the story reflects a memory of real transformation during the early phase of human history.",poem:false},"The City of Uruk":{text:"We also get a sense of how the city was divided during this time, suggesting some level of urban planning from its rulers.",poem:false},"Ur and Lagash":{text:"One carved stone monument from this time, \u201cSteale of Vultures\u201d, captures the spirit of this time.",poem:false},"Sargon of Akkad":{text:"In this time of chaos and instability, the other great people of Mesopotamia began to fancy their chance in ruling.",poem:false},"Sumer rises again":{text:"For the first time since the time of Sargon, the power of Mesopotamia was back in the hands of a Sumerian king again.",poem:false},"The Fall of Sumer":{text:"Ultimately, it was the landscape that had given birth to Ur, and it was the landscape that would bring its death.",poem:false},"\u0909\u0938\u0915\u093e \u0932\u093e\u0917\u093f \u0915\u0935\u093f\u0924\u093e\u0964":{text:"\u092f\u0940 \u0935\u093f\u0917\u0924\u0915\u093e \u0936\u092c\u094d\u0926\u093e\u0935\u0932\u0940\u0939\u0930\u0942 \u0915\u0947\u0939\u093f \u091b\u0948\u0928\u0928,\n\u091b\u0928 \u0924 \u0915\u0947\u0935\u0932, \u0905\u0928\u0940 \u0915\u0947\u0935\u0932,\n\u0928\u093f\u0936\u094d\u091a\u0932, \u0905\u0938\u0940\u092e\u093f\u0924, \u0905\u0928\u094d\u0924\u0939\u0940\u0928, \u0915\u094b\u092e\u0932 \u092e\u093e\u092f\u093e, \u092e\u093e\u0924\u094d\u0930\u0948 \u092e\u093e\u092f\u093e\u0964",poem:true},"\u091b\u093e\u0909\u092a\u0921\u0940\u0915\u094b \u091b\u093e\u092f\u093e\u0901":{text:"\u0918\u0930\u0915\u093e \u0906\u0901\u0916\u093e \u0922\u093e\u0915\u093f\u090f\u0915\u093e \u091d\u094d\u092f\u093e\u0932\u0939\u0930\u0942\u0964\n\u0924\u0930 \u0909\u0939\u0940 \u092d\u093f\u0924\u094d\u0924\u093e\u092d\u093f\u0924\u094d\u0930 \u092e\u0947\u0930\u094b \u0906\u0924\u094d\u092e\u093e\n\u092a\u0930\u092e\u094d\u092a\u0930\u093e\u0915\u094b \u0921\u0930\u0932\u0947 \u092b\u0947\u0930\u093f \u092e\u094c\u0928 \u092c\u0938\u094d\u091b\u0964",poem:true},"\u0928\u094b\u0938\u094d\u091f\u093e\u0932\u091c\u093f\u092f\u093e \u092a\u0938\u0932":{text:"\u0905\u0927\u0941\u0930\u094b \u0905\u0928\u0941\u0939\u093e\u0930 \u092c\u093e\u0901\u091a\u0947\u0915\u094b \u091b\n\u091f\u094d\u0930\u093e\u092b\u093f\u0915\u0915\u094b \u0915\u094b\u0932\u093e\u0939\u0932\u092e\u093e\n\u0909\u0938\u0915\u094b \u0906\u0935\u093e\u091c \u0905\u091d\u0948 \u0928\u094d\u092f\u093e\u0928\u094b \u092c\u091c\u094d\u091b\u0964",poem:true},"\u0915\u094b\u0920\u093e\u092d\u093f\u0924\u094d\u0930\u0915\u094b \u092e\u093e\u0928\u091a\u093f\u0924\u094d\u0930":{text:"\u092e\u0947\u0930\u094b \u0905\u0928\u0941\u0939\u093e\u0930 \u091a\u093f\u0924\u094d\u0930\u094d\u091b\u0928\u094d\u0964\n\u092e\u0947\u0930\u094b \u0924\u094d\u092f\u094b \u0905\u0928\u0941\u0939\u093e\u0930\u092e\u093e-\n\u0928\u093e\u0915 \u091b\u0948\u0928, \u0913\u0920 \u091b\u0948\u0928\u0964",poem:true},"Dear you, I hope you.":{text:"I told myself- I\u2019d stop here, fold the paper, hide it in some drawer and never let it breathe a daylight.",poem:false},"\u092a\u094d\u0930\u093f\u092f \u0924\u093f\u092e\u0940, \u092e \u0924\u093f\u092e\u094d\u0930\u094b \u0906\u0936 \u0917\u0930\u094d\u091b\u0941\u0964":{text:"\u092f\u0926\u093f \u092f\u094b \u092a\u0920\u093e\u090f\u0901 \u092d\u0928\u0947, \u0924\u093f\u092e\u0940\u0932\u093e\u0908 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915\u0924\u093e\u092e\u093e \u092e\u093e\u0924\u094d\u0930 \u0939\u094b\u0907\u0928, \u092e\u0947\u0930\u094b \u0915\u0932\u094d\u092a\u0928\u093e\u092e\u093e \u092a\u0928\u093f \u0917\u0941\u092e\u093e\u0909\u0901\u091b\u0941 \u092d\u0928\u094d\u0928\u0947 \u0921\u0930 \u091b, \u0930 \u0924\u094d\u092f\u094b \u0905\u0938\u0939\u094d\u092f \u0939\u0941\u0928\u0947\u091b\u0964",poem:false},"\u092a\u094d\u0930\u093f\u092f \u092e, (\u0910\u0928\u093e\u092d\u093f\u0924\u094d\u0930\u0915\u094b \u092a\u0924\u094d\u0930)":{text:"\u0928\u092f\u093e\u0901 \u0915\u0935\u093f\u0924\u093e\u0915\u094b \u092a\u093e\u0928\u093e\u092e\u093e \u092c\u0926\u0932\u094d\u091b\u0964\n\u091c\u0939\u093e\u0901- \u0924\u093f\u092e\u0940 \u0906\u092b\u0942 \u0928\u0939\u0941\u0928\u0941\u0915\u094b \u092a\u0940\u0921\u093e \u092e\u0939\u0938\u0941\u0938 \u0917\u0930\u094d\u091b\u094c,\n\u091c\u0938\u0932\u0947- \u0905\u091d\u0948 \u0924\u093f\u092e\u0940\u0932\u093e\u0908 \u091c\u093f\u091c\u0940\u0935\u093f\u0937\u093e \u0938\u093f\u0915\u093e\u0907\u0930\u0939\u0947\u0915\u093e \u091b\u0928\u094d\u0964",poem:true},"\u0935\u093e\u0926\u094d\u092f\u0939\u0930\u0942\u0915\u094b \u0935\u093f\u0930\u094b\u0927 \u0938\u0902\u0917\u093f\u0924":{text:"\u092e\u0947\u0930\u094b \u0938\u094d\u0935\u0930\u0932\u0947 \u092e\u093e\u0924\u0943\u092d\u093e\u0937\u093e\u0915\u094b \u092a\u0939\u093f\u091a\u093e\u0928 \u092b\u0941\u0915\u093e\u0932\u094b\u0938\u094d\n\u0935\u093f\u0926\u094d\u092f\u093e\u0932\u092f\u0915\u094b \u092a\u093e\u0920\u094d\u092f\u092a\u0941\u0938\u094d\u0924\u0915\u092e\u093e,\n\u0938\u092d\u093e\u0915\u094b \u092d\u093e\u0937\u093e\u092e\u093e, \u0915\u093e\u0928\u0941\u0928\u0915\u094b \u0936\u092c\u094d\u0926\u092e\u093e\u0964",poem:true},"\u091b\u093e\u092f\u093e\u0901\u092e\u093e \u0932\u0941\u0915\u0947\u0915\u094b \u0909\u091c\u094d\u092f\u093e\u0932\u094b\u0915\u094b \u0938\u0924\u094d\u092f":{text:"\u092a\u0939\u093e\u0921 \u092b\u094b\u0930\u0947\u0930 \u092c\u0917\u0947\u0915\u094b \u0939\u0941\u0928\u094d\u091b,\n\u092e \u092c\u094b\u0932\u094d\u091b\u0941, \u0909\u0938\u0932\u0947 \u0938\u0941\u0928\u094d\u091b,\n\u092e \u0939\u093f\u0901\u0921\u094d\u091b\u0941, \u0909\u0938\u0932\u0947 \u092c\u093e\u091f\u094b \u0938\u092e\u094d\u091d\u093f\u0928\u094d\u091b\u0964",poem:true},"\u092e\u094c\u0928\u0924\u093e\u0915\u094b \u091a\u093f\u0938\u094b":{text:"\u092e \u0924\u093f, \u092a\u094d\u0930\u0936\u094d\u0928\u0939\u0930\u0942\u092e\u0948 \u092c\u093e\u0901\u091a\u093f\u0930\u0939\u0947\u0915\u094b \u091b\u0941\u0964\n\u0928 \u092a\u0930\u094d\u0916\u093e\u0907\u0915\u094b \u0938\u092e\u092f \u091f\u0941\u0919\u094d\u0917\u093f\u0928\u094d\u091b,\n\u0928 \u092b\u0930\u094d\u0915\u093e\u0907\u0915\u094b \u092c\u093e\u091f\u094b \u0916\u0941\u0932\u094d\u091b\u0964",poem:true},"\u0905\u0928\u094d\u0924\u0930\u0947\u0915\u094b \u0915\u0925\u093e":{text:"\u0935\u0930\u094d\u0937\u0915\u094b \u0926\u0941\u0908 \u092a\u091f\u0915 \u0927\u0930\u093e\u0928 \u091d\u0930\u094d\u200d\u092f\u094b, \u092a\u0947\u0928\u094d\u0938\u0928, \u0928\u0941\u0928-\u091a\u093e\u092e\u0932 \u092c\u094b\u0915\u0947\u0930 \u092b\u0930\u094d\u0915\u093f\u092f\u094b, \u0924\u094d\u092f\u0924\u093f \u092a\u0948\u0938\u093e\u0932\u0947 \u092a\u0941\u0917\u093f\u0939\u093e\u0932\u094d\u0928\u0947, \u0928\u093f\u0915\u0948 \u0938\u092e\u092f \u092a\u0939\u093e\u0921\u092e\u0948 \u092c\u0938\u0947\u0915\u093e \u0925\u093f\u090f, \u092a\u0942\u0930\u094d\u0935\u091b\u093e\u0928\u0947\u0964",poem:false},"\u0918\u094b\u0937\u0923\u093e\u092a\u0924\u094d\u0930, \u092d\u0935\u093f\u0937\u094d\u092f \u0917\u0941\u092e\u093e\u090f\u0915\u094b \u0926\u0947\u0936\u092e\u093e \u0930\u093e\u0937\u094d\u091f\u094d\u0930\u093f\u092f \u0925\u0915\u093e\u0928\u0915\u094b":{text:"\u0939\u093e\u0935\u093e\u0915\u094b \u0926\u093f\u0936\u093e\u0938\u0901\u0917 \u091a\u0932\u093f \u0928\u0948 \u0930\u0939\u094d\u092f\u094b,\n\u0927\u0941\u0932\u094b\u092e\u093e \u0928\u093e\u0930\u093e \u091a\u0930\u094d\u0915\u094b \u0938\u0941\u0928\u093f\u0928\u094d\u091b\n\u0930, \u092e\u093e\u0928\u0935\u0924\u093e \u092c\u093f\u0930\u094d\u0938\u093f\u0907\u0928\u0947 \u0930\u0939\u0947\u091b\u0964",poem:true},"\u092c\u0939\u0941\u0932\u093e \u0930\u093e\u091c\u093e \u0930\u0923\u092c\u0939\u093e\u0926\u0941\u0930\u0915\u094b \u0926\u0930\u092c\u093e\u0930":{text:"\u0936\u0940\u0924\u0932\u093e \u092e\u093e\u091c\u0941, \u0915\u0947\u0935\u0932 \u092e\u0939\u093e\u092e\u093e\u0930\u0940\u0915\u094b \u0915\u0925\u093e \u0939\u094b\u0907\u0928, \u0924\u094d\u092f\u094b \u0938\u092e\u092f\u092e\u093e \u092d\u090f\u0915\u094b \u091c\u093e\u0924\u0940\u092f \u0905\u0928\u094d\u092f\u093e\u092f \u0930 \u0930\u093e\u091c\u093e\u0915\u094b \u092a\u093e\u0917\u0932\u092a\u0928\u0915\u094b \u0910\u0924\u093f\u0939\u093e\u0938\u093f\u0915 \u0926\u0938\u094d\u0924\u093e\u092c\u0947\u091c \u092a\u0928\u093f \u0939\u094b\u0964",poem:false},"\u092b\u0947\u0930\u093f, \u092b\u0947\u0930\u093f, \u092b\u0947\u0930\u093f":{text:"\u0939\u093e\u092e\u0940\u0932\u093e\u0908 \u091a\u0932\u093e\u0909\u0901\u091b\u0928\u094d-\n\u0939\u093e\u092e\u094d\u0930\u094b \u091a\u093e\u0939\u0928\u093e \u0939\u094b\u0907\u0928,\n\u0909\u0928\u0940\u0939\u0930\u0942\u0915\u094b \u0928\u093f\u0930\u0928\u094d\u0924\u0930 \u091a\u092e\u094d\u0915\u093e\u0907\u0964",poem:true},"The curious case of eels- how do eels reproduce?":{text:"The smallest eel larvae ever found, only millimeters long, have all been collected within or at the edges of the Sargasso Sea.",poem:false},"Dark antigens and Transposons":{text:"And some come from transposons: fleeting proteins that appear briefly, vanish quickly, and leave no imprint on immune memory.",poem:false},"The Genetic Prison":{text:"At one time, the Habsburg family ruling Spain married only within their own family for a long time to preserve royal purity.",poem:false},"Lobsters, Telomerase, and Aging":{text:"Only stem cells, germ cells, and certain immune compartments have enough activity to maintain long-term replicative capacity.",poem:false},"COVID-19: The Biological Process of SARS-CoV2 Infection and the Deepening Question of Long COVID.":{text:"After COVID-19 infection, the immune system is weakened; soldiers are either killed in the war or are extremely exhausted.",poem:false},"\u091c\u0941\u0920\u0940 \u0926\u092e\u093f\u0928\u0940\u0915\u094b \u091b\u093e\u092f\u093e\u0901\u092a\u093e\u0930\u093f":{text:"\u0926\u0947\u0909\u0924\u093e\u0915\u093e \u091b\u093e\u092f\u093e\u0939\u0930\u0942\u0915\u094b \u092a\u0938\u0932 \u091c\u0939\u093e\u0901,\n\u092a\u0935\u093f\u0924\u094d\u0930\u0924\u093e \u091b\u093e\u0932\u093e\u0915\u094b \u0930\u0919 \u0930\n\u0939\u093e\u0924\u0915\u094b \u0915\u093e\u092e\u0932\u0947 \u0928\u093e\u092a\u093f\u0928\u094d\u091b\u0964",poem:true},"\u0938\u0939\u0930\u092d\u093f\u0924\u094d\u0930\u0915\u094b \u0905\u0932\u093f\u0915\u0924\u093f \u0906\u0936":{text:"\u0924\u093f\u092e\u0940 \u092f\u0939\u093e\u0901 \u0932\u094d\u092f\u093e\u0907\u090f\u0915\u093e \u0939\u094b\u0907\u0928\u094c\u0964\n\u0924\u093f\u092e\u0940 \u0906\u092b\u0948\u0901 \u0906\u0907\u092a\u0941\u0917\u0947\u0915\u093e \u0939\u094c -\n\u0925\u0915\u093f\u0924 \u0928\u093f\u0930\u094d\u0923\u092f\u0939\u0930\u0942\u0915\u094b \u092c\u093e\u091f\u094b \u0939\u0941\u0901\u0926\u0948\u0964",poem:true},"\u0915\u093e\u092e\u0930\u0947\u0921\u0938\u0901\u0917\u0915\u094b \u092a\u0941\u0928\u0930\u094d\u092e\u093f\u0932\u0928":{text:"\u0924\u093f\u092e\u0940\u0932\u0947 \u0926\u093f\u090f\u0915\u094b \u092d\u093e\u0937\u0923 \u092a\u0928\u093f\n\u0915\u093e\u091f\u0940\u0915\u0941\u091f\u0940 \u0924\u093f\u092e\u094d\u0930\u093e \u092c\u093e\u0915\u094b \u091c\u0938\u094d\u0924\u0948 \u0926\u0947\u0916\u093f\u092f\u094b\u0964\n\u092f\u094b \u092d\u093e\u0937\u0923 \u092a\u0928\u093f \u0909\u0939\u0940 \u0939\u094b \u0915\u093f \u0915\u094d\u092f\u093e \u0939\u094b?",poem:true},"\u092a\u0943\u0925\u094d\u0935\u0940\u0928\u093e\u0930\u093e\u092f\u0923\u0938\u0901\u0917\u0915\u094b \u091c\u092e\u094d\u0915\u093e\u092d\u0947\u091f":{text:"\u0936\u093e\u0938\u0928 \u0924 \u092b\u0947\u0930\u093f\u092f\u094b, \u0924\u0930 \u091c\u0919\u094d\u0917\u092c\u0939\u093e\u0926\u0941\u0930\u0915\u094b \u0918\u094b\u0921\u093e\n\u0905\u091d\u0948 \u092a\u0928\u093f \u0938\u0939\u0930\u0915\u094b \u0917\u0932\u094d\u0932\u0940\u092e\u093e \u091c\u0928\u0924\u093e \u0915\u0941\u0932\u094d\u091a\u0901\u0926\u0948\u091b\u0964\n\u091c\u0919\u094d\u0917\u092c\u0939\u093e\u0926\u0941\u0930! \u0924\u093f\u092e\u0940\u0932\u0947 \u092a\u0928\u093f \u0906\u092b\u094d\u0928\u093e \u092d\u093e\u0907-\u092d\u093e\u0930\u0926\u093e\u0930\u0932\u093e\u0908 \u0930\u093e\u091c\u0926\u0942\u0924 \u092c\u0928\u093e\u092f\u094c \u0915\u093f?",poem:true},"\u0905\u0918\u094b\u0937\u093f\u0924 \u092e\u093e\u092f\u093e":{text:"\u091a\u0947\u0924\u0928\u093e\u0915\u094b \u090f\u0909\u091f\u093e \u091b\u093e\u0932 \u0906\u0909\u0901\u091b,\n\u0924\u093f\u092e\u094d\u0930\u094b \u092f\u093e\u0926\u0932\u093e\u0908 \u0915\u093f\u0928\u093e\u0930\u092e\u093e \u091b\u094b\u0921\u094d\u091b,\n\u0930 \u092b\u0947\u0930\u093f \u0906\u092b\u094d\u0928\u0948 \u0917\u0939\u093f\u0930\u093e\u0907\u0924\u093f\u0930 \u092b\u0930\u094d\u0915\u0928\u094d\u091b\u0964",poem:true},"\u0915\u093e\u0902\u0917\u094d\u0930\u0947\u0938: \u0935\u093f\u0930\u093e\u0938\u0924\u0915\u094b \u0935\u093f\u091c\u094d\u091e\u093e\u092a\u0928":{text:"\u0917\u0917\u0928\u0939\u0930\u0942 \u0906\u090f-\n\u092a\u094d\u0930\u0936\u094d\u0928 \u0932\u093f\u090f\u0930,\n\u0906\u0915\u094d\u0930\u094b\u0936 \u092c\u094b\u0915\u0947\u0930\u0964",poem:true},"Faith Before Hunger":{text:"While G\xf6bekli was mainly a ritual center or temple, Boncuklu Tarla had already become a full-time \u2018human settlement.\u2019",poem:false},"\u0905\u092c \u0930\u092e\u093f\u0924\u093e \u091b":{text:"\u0924\u0940 \u091a\u093f\u0938\u093e \u0928\u092d\u0948\u0938\u0947\u0915\u093e \u0936\u0930\u0940\u0930\u0939\u0930\u0942\u0915\u094b\n\u0938\u092a\u0928\u093e\u0939\u0930\u0941 \u0922\u093e\u0932\u093f\u090f\u0915\u094b \u0906\u0901\u0936\u0941\u092c\u093e\u091f\n\u091c\u0928\u094d\u092e\u093f\u090f\u0915\u094b \u0906\u0915\u094d\u0930\u094b\u0936\u0915\u093e \u0909\u0924\u094d\u0938\u0935\u0964",poem:true},"The Architecture of a Cure":{text:"But in humans, tumors proved resourceful, finding alternative vascular routes, and the \u201ccure\u201d never materialized as promised .",poem:false},"Happy Birthday":{text:"And somehow, that has always mattered more than proximity, more than continuity, more than the neatness of outcomes.",poem:false},"\u092e\u093f\u0928\u092a\u091a\u093e\u0938\u0915\u094b \u091c\u093e\u0921\u094b\u092e\u093e \u0915\u0920\u094d\u092f\u093e\u0902\u0917\u094d\u0930\u093f\u090f\u0915\u094b \u0926\u0947\u0936":{text:"\u092a\u0941\u0930\u093e\u0928\u093e\u092a\u094d\u0930\u0924\u093f\u0915\u094b \u0930\u093f\u0938\n\u0928\u092f\u093e\u0901\u0932\u093e\u0908 \u092d\u094b\u091f \u0926\u093f\u0928\u0947\n\u0938\u092c\u0948\u092d\u0928\u094d\u0926\u093e \u092c\u0932\u093f\u092f\u094b \u0924\u0930\u094d\u0915 \u092c\u0928\u0947\u0915\u094b \u091b\u0964",poem:true},"The Name I once wore":{text:"Leaving the baggage on the porch by the door.\nThe seasons are shifting, the air\u2019s turning cold,\nI\u2019m buying my stories back from the old.",poem:true},"The Story of Roman Britain Part I":{text:"This time he pushed inland, crossed the Thames, and forced the powerful tribal leader Cassivellaunus to sue for peace.",poem:false},marginalia:{text:"say it, Ana\xefs says.\n\u2018out loud. What you do.\u2019\nlaughing at the whole scandal.",poem:true},"\u0936\u0940\u0930\u094d\u0937\u0915\u0935\u093f\u0939\u0940\u0928":{text:"\u091a\u094c\u0916\u091f\u0932\u0947 \u092e\u0932\u093e\u0908 \u0928\u091a\u093f\u0928\u0940 \u092c\u0938\u094d\u0928\u0947\u091b\u0964\n\u091a\u0941\u0915\u0941\u0932 \u0905\u0939\u093f\u0932\u0947 \u0915\u0938\u0948\u0932\u0947 \u0924\u0947\u0932 \u0939\u093e\u0932\u093f\u0938\u0915\u094d\u092f\u094b \u0939\u094b\u0932\u093e\u0964\n\u092c\u0924\u094d\u0924\u0940\u0915\u094b \u0938\u094d\u0935\u093f\u091a \u0905\u0930\u094d\u0915\u0948\u0915\u094b \u0939\u093e\u0924\u0932\u0947 \u092d\u0947\u091f\u094d\u091f\u093e\u0909\u0928\u0947 \u091b\u0964",poem:true},"The Long Way Back":{text:"from here the kitchen is always warm.\nfrom here the lamp is always lit\nin the window I am always almost reaching.",poem:true},"Rosalind Franklin":{text:"This result, which held not only for humans, hinted that DNA\u2019s strands might somehow be joined as complements of each other.",poem:false},"Cancer Is Beaten in Mice. When in Humans?":{text:"Blocking EGFR and STAT3 at the same time could seriously affect the skin, the gut or the immune system.",poem:false},"\u092e\u0941\u0938\u093e\u092e\u093e \u0915\u094d\u092f\u093e\u0928\u094d\u0938\u0930 \u091c\u093f\u0924\u093f\u092f\u094b, \u092e\u093e\u0928\u093f\u0938\u092e\u093e \u0915\u0939\u093f\u0932\u0947?":{text:"\u092e\u0941\u0938\u093e\u0915\u094b \u091c\u0940\u0935\u0928\u091a\u0915\u094d\u0930 \u091b\u094b\u091f\u094b \u0939\u0941\u0928\u094d\u091b \u0930 \u092f\u093f\u0928\u0932\u0947 \u0915\u0947\u0939\u0940 \u0939\u092a\u094d\u0924\u093e\u0915\u094b \u0915\u0921\u093e \u0909\u092a\u091a\u093e\u0930 \u0927\u093e\u0928\u094d\u0928 \u0938\u0915\u094d\u091b\u0928\u094d; \u0924\u0930 \u092e\u093e\u0928\u093f\u0938\u0932\u0947 \u092e\u0939\u093f\u0928\u094c\u0901 \u0927\u093e\u0928\u094d\u0928\u0941\u092a\u0930\u094d\u091b\u0964",poem:false},"\u0930\u094b\u091c\u093e\u0932\u093f\u0928\u094d\u0921 \u092b\u094d\u0930\u093e\u0902\u0915\u0932\u093f\u0928":{text:"\u0928\u094d\u092f\u0941\u0915\u094d\u0932\u093f\u092f\u094b\u091f\u093e\u0907\u0921\u092d\u093f\u0924\u094d\u0930 \u0939\u0941\u0928\u0947 \u092b\u094b\u0938\u094d\u092a\u0947\u091f, \u091a\u093f\u0928\u0940 \u0905\u0928\u093f \u0928\u093e\u0907\u091f\u094d\u0930\u094b\u091c \u092c\u0947\u0938\u0932\u093e\u0908 \u0916\u094b\u0924\u0932\u0947\u0930 \u092a\u094d\u0930\u0938\u094d\u091f \u092a\u093e\u0930\u094d\u0928\u0947 \u0915\u093e\u092e\u091a\u093e\u0939\u093f\u0901 \u0905\u0932\u0947\u0915\u094d\u091c\u0947\u0928\u094d\u0921\u0930 \u091f\u094b\u0921\u0932\u0947 \u0928\u093f\u0915\u0948 \u092a\u091b\u093f \u0917\u0930\u0947\u0915\u093e \u0925\u093f\u090f\u0964",poem:false},"How DNA Copies Itself":{text:"The enzyme that makes DNA\u2019s new strand, DNA polymerase III, can add nucleotides to a new strand only in the 5\u2032\u20133\u2032 direction.",poem:false},"\u091c\u093f\u0928 \u0930 \u0921\u0940\u090f\u0928\u090f\u0932\u0947 \u0915\u0938\u0930\u0940 \u0906\u092b\u094d\u0928\u094b \u092a\u094d\u0930\u0924\u093f\u0932\u093f\u092a\u093f \u092c\u0928\u093e\u0909\u0901\u091b\u0928\u094d?":{text:"\u0915\u094d\u0930\u094b\u092e\u094b\u091c\u094b\u092e\u092e\u093e \u0921\u0940\u090f\u0928\u090f\u092d\u0928\u094d\u0926\u093e \u0927\u0947\u0930\u0948 \u092c\u0922\u0940 \u0924 \u092a\u094d\u0930\u094b\u091f\u093f\u0928\u0939\u0930\u0942 \u092d\u0947\u091f\u093f\u0928\u094d\u091b\u0928\u094d\u0964\u092a\u094d\u0930\u094b\u091f\u093f\u0928\u0939\u0930\u0942 \u0921\u0940\u090f\u0928\u090f\u092d\u0928\u094d\u0926\u093e \u092a\u094d\u0930\u0936\u0938\u094d\u0924, \u0920\u0942\u0932\u093e \u0930 \u091c\u091f\u093f\u0932 \u0938\u0902\u0930\u091a\u0928\u093e \u092d\u090f\u0915\u093e \u0939\u0941\u0928\u094d\u091b\u0928\u094d\u0964",poem:false},"Cousin Marriage & Genetic Disease":{text:"By the time excavators found and opened them, robbers had usually already carried off the mummies and other offerings.",poem:false},"COVID-19, Long COVID and the Old Diseases It Reawakens":{text:"At such a time, internal security in the capital and other cities weakens, and hidden enemies within get a chance to rise up.",poem:false},"Why Don\u2019t Elephants Get Cancer the Way Humans Do?":{text:"One way to understand this is that only a small founding group from Africa left Africa, and today\u2019s modern humans are descended from them.",poem:false},"\u092e\u093e\u092e\u093e\u091a\u0947\u0932\u093e \u092b\u0941\u092a\u0942\u091a\u0947\u0932\u093e \u092c\u093f\u0939\u0947\u0915\u093e \u0938\u094d\u0935\u093e\u0938\u094d\u0925\u094d\u092f \u0938\u092e\u0938\u094d\u092f\u093e":{text:"\u092f\u0941\u0930\u094b\u092a\u092e\u093e \u092e\u093e\u0924\u094d\u0930\u0948 \u0939\u094b\u0907\u0928, \u091c\u093e\u092a\u093e\u0928\u0915\u093e \u0930\u093e\u091c\u092a\u0930\u093f\u0935\u093e\u0930\u092e\u093e \u092a\u0928\u093f \u0915\u0941\u0928\u0948 \u0938\u092e\u092f \u0930\u093e\u091c\u0927\u093e\u0928\u0940\u0915\u093e \u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u091a\u093e\u0930-\u092a\u0930\u093f\u0935\u093e\u0930 \u092d\u093f\u0924\u094d\u0930 \u092e\u093e\u0924\u094d\u0930\u0948 \u092c\u093f\u0939\u0947\u092c\u093e\u0930\u0940 \u0917\u0930\u094d\u0928\u0947 \u091a\u0932\u0928 \u0925\u093f\u092f\u094b\u0964",poem:false},"\u0936\u0930\u0940\u0930\u0932\u0947 \u0928\u092f\u093e\u0901 \u092e\u093f\u0930\u094d\u0917\u094c\u0932\u093e\u0932\u093e\u0908 \u0915\u093f\u0928 \u0936\u0924\u094d\u0930\u0941 \u0920\u093e\u0928\u094d\u091b?":{text:"\u0924\u094d\u092f\u0924\u093f \u092e\u093e\u0924\u094d\u0930\u0948 \u0939\u094b\u0907\u0928, \u0915\u0939\u093f\u0932\u0947-\u0915\u0939\u093f\u0932\u0947\u0915\u093e \u092a\u0941\u0930\u094d\u0916\u093e\u0939\u0930\u0942\u0932\u093e\u0908 \u0932\u093e\u0917\u0947\u0915\u094b \u0930\u094b\u0917\u0939\u0930\u0942\u0915\u094b \u0938\u092e\u094d\u091d\u0928\u093e \u0930 \u0924\u0940 \u0930\u094b\u0917\u0939\u0930\u0942\u092c\u093e\u091f \u092c\u093e\u0901\u091a\u094d\u0928\u0947 \u0915\u094d\u0937\u092e\u0924\u093e \u092a\u0928\u093f \u092f\u093f\u0928\u0940\u0939\u0930\u0942\u092e\u093e \u0928\u0948 \u0928\u093f\u0939\u093f\u0924 \u0939\u0941\u0928\u094d\u091b\u0964",poem:false},"Why Does the Body Treat a New Kidney as an Enemy?":{text:"Although innate immunity is always active and can fight many threats, it doesn\u2019t recognize specific invaders and is not very effective.",poem:false},"\u0915\u094b\u092d\u093f\u0921-\u0967\u096f \u0938\u0902\u0915\u094d\u0930\u092e\u0923, \u0932\u0919-\u0915\u094b\u092d\u093f\u0921 \u0930 \u092c\u094d\u092f\u0941\u0901\u0924\u093f\u090f\u0915\u093e \u092a\u0941\u0930\u093e\u0928\u093e \u0930\u094b\u0917":{text:"\u092f\u094b \u092d\u093e\u0907\u0930\u0938 \u0915\u0939\u093f\u0932\u094d\u092f\u0948 \u0915\u094b\u0937\u0915\u094b \u0928\u094d\u092f\u0941\u0915\u094d\u0932\u093f\u092f\u0938\u092d\u093f\u0924\u094d\u0930 \u092a\u094d\u0930\u0935\u0947\u0936 \u0917\u0930\u094d\u0926\u0948\u0928 \u0930 \u0939\u093e\u092e\u094d\u0930\u094b \u0921\u0940\u090f\u0928\u090f\u0938\u0901\u0917 \u0915\u0941\u0928\u0948 \u092a\u0928\u093f \u092a\u094d\u0930\u0915\u093e\u0930\u0932\u0947 \u092e\u093f\u0938\u093f\u0928\u0947 \u0915\u094d\u0937\u092e\u0924\u093e \u092f\u0938\u092e\u093e \u0939\u0941\u0901\u0926\u0948\u0928\u0964",poem:false},"\u0939\u093e\u0924\u094d\u0924\u0940\u0932\u093e\u0908 \u092e\u093e\u0928\u093f\u0938\u091d\u0948\u0901 \u0915\u094d\u092f\u093e\u0928\u094d\u0938\u0930 \u0915\u093f\u0928 \u0932\u093e\u0917\u094d\u0926\u0948\u0928?":{text:"\u092a\u0930\u093f\u0923\u093e\u092e \u0938\u094d\u0935\u0930\u0942\u092a, \u0939\u093e\u092e\u094d\u0930\u094b \u0915\u094d\u0930\u094b\u092e\u094b\u091c\u094b\u092e\u092e\u093e \u0932\u093e\u092e\u094b \u0938\u092e\u092f\u0926\u0947\u0916\u093f \u090f\u0915 \u0905\u0930\u094d\u0915\u093e\u092c\u093e\u091f \u0905\u0932\u0917 \u092d\u0907\u0938\u0915\u094d\u0928\u0941\u092a\u0930\u094d\u0928\u0947 \u091c\u093f\u0928\u0915\u093e \u0916\u0923\u094d\u0921\u0939\u0930\u0942 \u092a\u0928\u093f \u0906\u091c\u0938\u092e\u094d\u092e \u090f\u0915\u0938\u093e\u0925 \u091c\u094b\u0921\u093f\u090f\u0930 \u092c\u0938\u0947\u0915\u094b \u092d\u0947\u091f\u093f\u0928\u094d\u091b\u0964",poem:false},"\u092c\u093e\u092e \u092e\u093e\u091b\u093e\u0915\u094b \u0930\u0939\u0938\u094d\u092f\u092e\u092f \u091c\u0940\u0935\u0928":{text:"\u092c\u093e\u092e \u092e\u093e\u091b\u093e\u0915\u094b \u0938\u092e\u094d\u092a\u0942\u0930\u094d\u0923 \u0936\u0930\u0940\u0930 \u0905\u092c \u090f\u0909\u091f\u0948 \u0909\u0926\u094d\u0926\u0947\u0936\u094d\u092f\u0915\u093e \u0932\u093e\u0917\u093f \u0922\u093e\u0932\u093f\u0928\u094d\u091b\u2014 \u0924\u094d\u092f\u094b \u090f\u0915\u0924\u0930\u094d\u092b\u0940 \u092f\u093e\u0924\u094d\u0930\u093e \u092a\u0942\u0930\u093e \u0917\u0930\u094d\u0928, \u091c\u0939\u093e\u0901\u092c\u093e\u091f \u092f\u094b \u0915\u0939\u093f\u0932\u094d\u092f\u0948 \u092b\u0930\u094d\u0915\u0928\u0947 \u091b\u0948\u0928\u0964",poem:false},"\u092d\u094b\u0915\u092d\u0928\u094d\u0926\u093e \u092a\u0939\u093f\u0932\u0947 \u0906\u0938\u094d\u0925\u093e! \u091c\u092c \u092e\u0928\u094d\u0926\u093f\u0930\u0932\u0947 \u0917\u093e\u0909\u0901 \u0930 \u0916\u0947\u0924\u0940 \u091c\u0928\u094d\u092e\u093e\u092f\u094b":{text:"\u0932\u093e\u092e\u094b \u0938\u092e\u092f\u0938\u092e\u094d\u092e \u0907\u0924\u093f\u0939\u093e\u0938\u0915\u093e\u0930\u0939\u0930\u0942\u0932\u0947 \u090f\u0909\u091f\u093e \u092d\u093e\u0937\u094d\u092f\u092e\u093e \u0935\u093f\u0936\u094d\u0935\u093e\u0938 \u0917\u0930\u0947\u2013\u092a\u0939\u093f\u0932\u0947 \u092e\u093e\u0928\u093f\u0938\u0939\u0930\u0942\u0932\u0947 \u0916\u0947\u0924\u0940 \u0917\u0930\u094d\u0928 \u0938\u093f\u0915\u0947, \u0924\u094d\u092f\u0938\u092a\u091b\u093f \u0938\u094d\u0925\u093e\u092f\u0940 \u0918\u0930 \u092c\u0928\u093e\u090f\u0964",poem:false},"\u0932\u092c\u094d\u0938\u094d\u091f\u0930 \u092c\u0941\u0922\u094b \u0939\u0941\u0901\u0926\u0948\u0928, \u0925\u0915\u093e\u0907\u0932\u0947 \u092e\u0930\u094d\u091b":{text:"\u092f\u094b \u0939\u093e\u092e\u094d\u0930\u0948 \u0938\u094b\u092e\u093e\u091f\u093f\u0915 \u0938\u0947\u0932\u0932\u0947 \u090f\u0915 \u0905\u0930\u094d\u092c \u0935\u0930\u094d\u0937\u0905\u0918\u093f \u0917\u0930\u0947\u0915\u094b \u0938\u092e\u094d\u091d\u094c\u0924\u093e \u0924\u094b\u0921\u0947\u0930 \u092a\u0941\u0930\u093e\u0928\u094b, \u090f\u0915\u0915\u094b\u0937\u0940\u092f \u091c\u0940\u0935\u0928\u0936\u0948\u0932\u0940\u092e\u093e \u092b\u0930\u094d\u0915\u0928\u0947 \u0917\u0930\u0947\u0915\u094b \u092a\u094d\u0930\u092f\u093e\u0938 \u0939\u094b\u0964",poem:false},"Lobsters Don\u2019t Age: Telomerase, Telomeres and the Price of Living Forever":{text:"For roughly the first three billion years, life on Earth carried on just like this: there was death, but no aging.",poem:false},"The Mysterious Life of the Eel":{text:"The eel\u2019s entire body is now shaped for a single purpose: to complete that one-way journey from which it will never return.",poem:false}};
