/* ---- a series page that works before the labels exist ----
   Each run links to /search/label/series-<name>. Blogger will serve that
   page properly once the posts carry the label, but none of them do yet, so
   today it would arrive empty. When that happens the page is built here
   instead, from the same KAFKA_SERIES list the homepage uses: the series
   name, how many pieces are in it, and every one of them in order. The
   moment you add the labels in Blogger, Blogger's own page takes over and
   this never runs. */
(function () {
  var m = location.pathname.match(/\/search\/label\/(series-[\w-]+)/);
  if (!m) return;
  var want = decodeURIComponent(m[1]);
  var S = (window.KAFKA_SERIES || []).filter(function (x) { return x[2] === want; })[0];
  if (!S) return;

  function esc(t) { return String(t).replace(/[&<>"]/g, function (c) {
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }

  function build(posts) {
    var host = document.querySelector('.main-section') || document.querySelector('.main');
    if (!host) return;
    var head = document.querySelector('.cat-head h1, .main h1');
    if (head) head.textContent = S[0];
    var sub = document.querySelector('.cat-head .count, .main .count');
    if (sub) sub.textContent = 'Series';

    host.innerHTML =
      '<header class="post-head cat-head"><p class="count">Series</p><h1>' + esc(S[0]) + '</h1>' +
      '<p class="post-sub">' + posts.length + (posts.length === 1 ? ' piece' : ' pieces') +
      ', in the order they were written.</p></header>' +
      '<ol class="serpage">' + posts.map(function (p, i) {
        return '<li><span class="n">' + (i + 1) + '</span>' +
          '<a class="th" href="' + esc(p.url) + '" tabindex="-1" aria-hidden="true">' +
          (p.cover ? '<img loading="lazy" alt="" src="' + esc(p.cover) + '"/>' : '') + '</a>' +
          '<span class="tx"><a class="tt" href="' + esc(p.url) + '">' + esc(p.title) + '</a>' +
          (p.sub ? '<span class="sb">' + esc(p.sub) + '</span>' : '') +
          '<span class="dt">' + p.when + '</span></span></li>';
      }).join('') + '</ol>';
  }

  fetch('/feeds/posts/default?alt=json&max-results=500')
    .then(function (r) { return r.json(); })
    .then(function (j) {
      var byTitle = {}, all = [];
      (j.feed.entry || []).forEach(function (e) {
        var t = window.KAFKA_NORM((e.title && e.title.$t) || '');
        var u = ((e.link || []).filter(function (l) { return l.rel === 'alternate'; })[0] || {}).href || '';
        var doc = new DOMParser().parseFromString('<body>' + ((e.content && e.content.$t) || '') + '</body>', 'text/html');
        var cov = doc.body.querySelector('.kafka-cover img');
        var subEl = doc.body.querySelector('.kafka-subtitle');
        var d = new Date(e.published.$t);
        var first_ = doc.body.querySelector('img[src]');                       // v71: a pasted piece has no cover block
        var rec = { title: t, url: u, cover: window.KAFKA_COVER(e.id.$t, cov ? cov.getAttribute('src') : (first_ ? first_.getAttribute('src') : '')),
          sub: subEl ? subEl.textContent.trim() : '',
          labels: window.KAFKA_LABELS(e.id.$t, (e.category || []).map(function (c) { return c.term; })),
          date: d, when: d.toLocaleDateString('en-GB', {day:'numeric', month:'long', year:'numeric'}) };
        byTitle[t] = rec; all.push(rec);
      });

      var seeds = S[3] || [], trig = S[1] || [], got = [];
      seeds.forEach(function (t) { if (byTitle[t] && got.indexOf(byTitle[t]) < 0) got.push(byTitle[t]); });
      all.forEach(function (p) {
        if (got.indexOf(p) > -1) return;
        if (S[2] && p.labels.indexOf(S[2]) > -1) { got.push(p); return; }
        for (var i = 0; i < trig.length; i++) {
          if (p.labels.some(function (x) { return String(x).toLowerCase() === String(trig[i]).toLowerCase(); })) { got.push(p); return; }
        }
      });
      got.sort(function (a, b) { return a.date - b.date; });
      if (got.length) build(got);
    }).catch(function () {});
})();
